class ListNode {
  constructor(val, next = null) { this.val = val; this.next = next; }
}

function buildCyclicList(vals, cycleStartIdx) {
  if (!vals.length) return null;
  const nodes = vals.map(v => new ListNode(v));
  for (let i = 0; i < nodes.length - 1; i++) nodes[i].next = nodes[i + 1];
  if (cycleStartIdx >= 0 && cycleStartIdx < nodes.length) {
    nodes[nodes.length - 1].next = nodes[cycleStartIdx];
  }
  return nodes[0];
}

function hasCycleImpl(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

function detectCycleImpl(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) break;
  }
  if (!fast || !fast.next) return null;
  slow = head;
  while (slow !== fast) {
    slow = slow.next;
    fast = fast.next;
  }
  return slow;
}

function cycleLengthImpl(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next; fast = fast.next.next;
    if (slow === fast) {
      let length = 1, curr = slow.next;
      while (curr !== slow) { length++; curr = curr.next; }
      return length;
    }
  }
  return 0;
}

